#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
using namespace std;

const int BIG = 1 << 29;
const int MAX_NODES = 500;

struct Connection {
    int source, sink, capacity, flow;
};

bool obstacles[11][11];
vector<int> adj[MAX_NODES];
vector<Connection> network;
int levels[MAX_NODES], nextEdge[MAX_NODES], N, src_r, src_c, T, dists[11][11], caps[11][11];

int dist(int r1, int c1, int r2, int c2) {
    queue<pair<int, pair<int, int>>> q;
    q.push({0, {r1, c1}});
    int h[11][11];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            h[i][j] = BIG;
    while (!q.empty()) {
        int d = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        h[x][y] = d;
        if (x > 0 && obstacles[x-1][y]) {
            int nx = x-1, ny = y;
            if (h[nx][ny] > d+1) {
                bool cond1 = (nx == r2 && ny == c2 && dists[nx][ny] >= d+1);
                bool cond2 = (!(nx == r2 && ny == c2) && dists[nx][ny] > d+1);
                if (cond1 || cond2) q.push({d+1, {nx, ny}});
            }
        }
        if (y > 0 && obstacles[x][y-1]) {
            int nx = x, ny = y-1;
            if (h[nx][ny] > d+1) {
                bool cond1 = (nx == r2 && ny == c2 && dists[nx][ny] >= d+1);
                bool cond2 = (!(nx == r2 && ny == c2) && dists[nx][ny] > d+1);
                if (cond1 || cond2) q.push({d+1, {nx, ny}});
            }
        }
        if (x < N-1 && obstacles[x+1][y]) {
            int nx = x+1, ny = y;
            if (h[nx][ny] > d+1) {
                bool cond1 = (nx == r2 && ny == c2 && dists[nx][ny] >= d+1);
                bool cond2 = (!(nx == r2 && ny == c2) && dists[nx][ny] > d+1);
                if (cond1 || cond2) q.push({d+1, {nx, ny}});
            }
        }
        if (y < N-1 && obstacles[x][y+1]) {
            int nx = x, ny = y+1;
            if (h[nx][ny] > d+1) {
                bool cond1 = (nx == r2 && ny == c2 && dists[nx][ny] >= d+1);
                bool cond2 = (!(nx == r2 && ny == c2) && dists[nx][ny] > d+1);
                if (cond1 || cond2) q.push({d+1, {nx, ny}});
            }
        }
    }
    return h[r2][c2];
}

void connect(int u, int v, int cap) {
    network.push_back({u, v, cap, 0});
    network.push_back({v, u, 0, 0});
    adj[u].push_back((int)network.size() - 2);
    adj[v].push_back((int)network.size() - 1);
}

bool bfs_levels() {
    fill(levels, levels + N*N*2+2, -1);
    queue<int> q;
    q.push(0);
    levels[0] = 0;
    while (!q.empty() && levels[N*N*2+1] == -1) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            int v = network[id].sink;
            if (levels[v] == -1 && network[id].flow < network[id].capacity) {
                levels[v] = levels[u] + 1;
                q.push(v);
            }
        }
    }
    return levels[N*N*2+1] != -1;
}

int dfs_path(int u, int flow) {
    if (!flow) return 0;
    if (u == N*N*2+1) return flow;
    for (; nextEdge[u] < (int)adj[u].size(); ++nextEdge[u]) {
        int id = adj[u][nextEdge[u]];
        int v = network[id].sink;
        if (levels[v] != levels[u] + 1) continue;
        int pushed = dfs_path(v, min(flow, network[id].capacity - network[id].flow));
        if (pushed) {
            network[id].flow += pushed;
            network[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int total = 0;
    while (bfs_levels()) {
        fill(nextEdge, nextEdge + N*N*2+2, 0);
        int delta;
        while ((delta = dfs_path(0, BIG)) > 0) total += delta;
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> T;
    queue<pair<int, pair<int, int>>> q;
    char c;
    int node = 1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> c;
            dists[i][j] = T;
            if (c == 'Z') {
                src_r = i;
                src_c = j;
                obstacles[i][j] = false;
            } else if (c == 'Y') {
                obstacles[i][j] = false;
            } else {
                obstacles[i][j] = true;
            }
            connect(0, node++, (c == 'Z' || c == 'Y') ? 0 : c - '0');
        }
    }
    node = N * N + 1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> c;
            if (c >= '0' && c <= '9') caps[i][j] = c - '0';
            connect(node++, N*N*2+1, (c == 'Z' || c == 'Y') ? 0 : c - '0');
        }
    }
    q.push({0, {src_r, src_c}});
    while (!q.empty()) {
        int d = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        dists[r][c] = d;
        if (r > 0 && d + 1 < dists[r - 1][c] && obstacles[r - 1][c])
            q.push({d + 1, {r - 1, c}});
        if (c > 0 && d + 1 < dists[r][c - 1] && obstacles[r][c - 1])
            q.push({d + 1, {r, c - 1}});
        if (r < N - 1 && d + 1 < dists[r + 1][c] && obstacles[r + 1][c])
            q.push({d + 1, {r + 1, c}});
        if (c < N - 1 && d + 1 < dists[r][c + 1] && obstacles[r][c + 1])
            q.push({d + 1, {r, c + 1}});
    }
    int idx = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int sink_node = N * N;
            ++idx;
            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    ++sink_node;
                    if (obstacles[i][j] && obstacles[x][y] && dist(i, j, x, y) <= T)
                        connect(idx, sink_node, BIG);
                }
            }
        }
    }
    cout << max_flow() << '\n';
    return 0;
}
